/* questions.js - dynamic multiple-choice generators (numbers re-rolled every run),
   topic -> unit / difficulty maps, and difficulty levels. Depends on js/core/util.js. */
/* ============ DYNAMIC QUESTION GENERATORS (numbers re-rolled every run) ============ */
const GEN=[
()=>{const j=R(4,9)*100000,c=R(2,5)*100000;const joint=Math.min(j,500000),ira=Math.min(c,500000);
 return Q(1,"SIPC separate capacity",`A couple holds: a joint brokerage account with ${money(j)} in securities, and one spouse's IRA with ${money(c)} in securities. The BD fails. What is the total SIPC coverage?`,
 [money(joint+ira),money(joint+ira+250000),money(500000),money(joint+ira-250000)],0,
 `Joint = ONE separate capacity (not per person): capped at $500k → ${money(joint)}. The IRA is a DIFFERENT capacity → another $500k cap → ${money(ira)}. Total ${money(joint+ira)}. Cash inside any capacity has a $250k sub-limit.`,"SIPC: $500k per separate capacity, $250k cash sub-limit. Joint ≠ 2 capacities.")},
()=>{const fall=Math.random()<.5;return Q(2,"CMO tranches",`Interest rates ${fall?"FALL sharply, prepayments surge":"RISE sharply, prepayments collapse"}. A CMO support (companion) tranche backing a PAC tranche will most likely experience:`,
 [fall?"Contraction — principal returned early, average life shortens":"Extension — principal returned late, average life lengthens","No change — PAC protection removes all prepayment risk","The PAC tranche absorbs excess prepayments before the support tranche","Immediate default of the PAC tranche"],0,
 fall?`Falling rates → homeowners refinance → prepayments surge → support tranche absorbs the excess first, so it CONTRACTS. Extension is the rising-rate case.`:`Rising rates → refinancing stops → prepayments dry up → support tranche is paid slower to keep the PAC on schedule, so it EXTENDS. Contraction is the falling-rate case.`,"Rates ↓ = contraction. Rates ↑ = extension. Support absorbs variability to protect the PAC.")},
()=>{const n=pick(NAMES);return Q(3,"Freeriding",`${n} has a cash account with zero available settled cash. Monday ${n} buys 200 shares without funds to cover, then sells those shares Tuesday before paying for the purchase. This is:`,
 ["Freeriding — a Reg T violation; account can be frozen 90 days","A legal day trade","A wash sale","Front running"],0,
 `Buying a security in a cash account without funds to pay and selling it before paying in full = freeriding (Reg T). Consequence: a single freeriding violation restricts the account to settled-funds-only for 90 calendar days (unless paid in full by Reg T settlement). Buying with unsettled sale proceeds and selling before the funding trade settles is a Good Faith Violation (3 GFVs in 12 months trigger the 90-day freeze).`,"Freeriding = buy + sell before paying, in a cash account.")},
()=>{const d=R(5,28);return Q(3,"Wash sale",`An investor sells a stock at a loss and repurchases a substantially identical security ${d} days later. Under the wash sale rule:`,
 ["The loss is disallowed for now and added to the cost basis of the new shares","The loss is permanently lost","Nothing happens — the rule only covers 61+ days","The loss is doubled as a penalty"],0,
 `30 days before or after the sale (61-day window total). ${d} days is inside it. The loss isn't destroyed — it's deferred into the new shares' basis, and the holding period tacks on.`,"Wash sale window: 30 days either side = 61 days total.")},
()=>{const amt=R(3,20)*2000;return Q(3,"Reg T margin",`Under Regulation T, an investor buys ${money(amt)} of marginable stock in a new margin account (above the $2,000 minimum equity requirement). The initial margin call is:`,
 [money(amt/2),money(amt),money(amt*.25),money(amt*.75)],0,
 `Reg T initial = 50% for listed/marginable equities → ${money(amt/2)} (note: FINRA Rule 4210 requires at least $2,000 minimum equity to open a margin account, or 100% if under $2,000). The 25% figure is FINRA's long maintenance minimum — don't swap them. Reg T is set by the Federal Reserve.`,"Reg T initial 50% (Fed). FINRA maintenance 25% long.")},
()=>Q(3,"Pattern day trader",`Under FINRA's classic Pattern Day Trader rule, a margin customer who executes 5 day trades within 5 business days (over 6% of total trades) must maintain minimum equity of:`,
 ["$25,000","$2,000","$5,000","$50,000"],0,`Traditional Pattern Day Trader rule = 4+ day trades in 5 business days AND >6% of trades → $25,000 minimum equity ($2,000 is the basic margin minimum). Note: FINRA approved replacing the $25,000 PDT threshold with risk-based intraday margin under SR-FINRA-2025-017 (June 4, 2026) during an 18-month transition.`,"Classic PDT: 4+ in 5 days, >6%, $25k equity (transitioning to intraday margin)."),
()=>Q(3,"Reg SHO",`Before a BD accepts a short sale order, Reg SHO's 'locate' requirement means the firm must:`,
 ["Have borrowed, arranged to borrow, or have reasonable grounds to believe the security can be borrowed so delivery can be made","Guarantee the price will fall","Hold 150% cash collateral","Get FINRA pre-approval for each order"],0,`Locate precedes the short sale. Failures to deliver trigger Rule 204 close-out requirements: settlement + 1 (T+2) for short-sale fails, or settlement + 3 for long sales and bona fide market making. Naked shorting without a locate is prohibited.`,"Reg SHO: locate first, close out short fails by S+1."),
()=>{const k=R(30,80),p=R(2,9);return Q(2,"Options — covered call",`An investor buys stock at $${k} and sells a $${k} call for $${p}. Maximum gain per share if called away is:`,
 [`$${p}`,`$${k+p}`,`Unlimited`,`$${k-p}`],0,`Covered call: stock bought at strike, called away at strike → stock gain $0, keep the $${p} premium. Max loss = $${k-p} (stock to zero, less premium). Breakeven = ${k}-${p} = $${k-p}.`,"Covered call: max gain = premium when strike = purchase price.")},
()=>Q(2,"Bond risk",`Which bond is MOST sensitive to interest-rate changes (highest duration)?`,
 ["A 30-year zero-coupon bond","A 30-year 8% coupon bond","A 5-year zero-coupon bond","A 2-year 8% coupon bond"],0,`Duration rises with maturity and falls with coupon. Longest maturity + zero coupon = highest duration = most price sensitivity. Prices move inverse to yields.`,"Duration: ↑ maturity, ↓ coupon → ↑ sensitivity."),
()=>Q(3,"Communications",`A firm sends a research piece to 40 retail investors in a 30-calendar-day period. Under FINRA Rule 2210 this is a 'retail communication' and generally requires:`,
 ["Approval by a principal before use (or within set exceptions)","SEC pre-approval","No approval ever","Approval only if it mentions options"],0,`Retail communication = distributed to MORE than 25 retail investors within any 30-calendar-day period → principal approval before use. 25 or fewer = correspondence (supervision/review standard, different rule). The 25/30 numbers are the trap.`,"Retail communication: >25 retail investors in 30 days."),
()=>Q(3,"Trusted contact / seniors",`Under FINRA Rule 4512 / 2165, a 'specified adult' a firm may protect with a temporary hold on disbursements or securities transactions is a customer who is:`,
 ["Age 65 or older, or 18+ where the firm reasonably believes diminished capacity exists","Age 55 or older","Any customer with a joint account","Only customers with a power of attorney"],0,`65+ automatically qualifies; 18+ qualifies if the firm reasonably believes diminished mental capacity. Trusted contact must be 18+. Rule 2165 allows temporary holds on both disbursements and securities transactions (up to 55 business days when reported to authorities).`,"Specified adult: 65+, or 18+ with reasonably-believed diminished capacity."),
()=>Q(3,"Discretionary accounts",`A rep may exercise discretion in a customer account only if:`,
 ["The customer gives prior written authorization AND the firm accepts the account as discretionary in writing","The customer verbally agrees once","The rep has known the customer 5 years","Discretion is limited to time/price only, always allowed"],0,`BOTH writings are required: customer's written grant + firm's written acceptance. Exception: time-and-price discretion (which security/how much is NOT discretionary) ending by the close of that business day needs no prior written grant.`,"Discretion = written customer grant + written firm acceptance. Time/price ≠ discretion."),
()=>Q(3,"Prohibited activities",`A rep buys shares of a stock personally, minutes before entering a large customer buy order expected to move the price. This is:`,
 ["Front running — prohibited","Dollar-cost averaging","A permitted hedge","Painting the tape"],0,`Trading ahead of a customer's block order for personal benefit = front running. Painting the tape / matched orders = creating a false appearance of activity — different label, also prohibited.`,"Front running = trading ahead of a known customer order."),
()=>Q(2,"Mutual fund pricing",`Mutual fund shares are priced under 'forward pricing.' An order received at 3:55 PM ET (before the 4:00 PM close) receives:`,
 ["That day's next-calculated NAV (4:00 PM price)","The prior day's NAV","The NAV at the moment the order was placed","Tomorrow's NAV"],0,`Forward pricing (Rule 22c-1): you get the NEXT NAV calculated after your order is received. Before 4 PM → today's 4 PM NAV. After 4 PM → tomorrow's. You never know the exact price when you order.`,"Forward pricing: next NAV after receipt."),
()=>Q(2,"Convertibles",`A convertible bond will most likely trade based primarily on its equity value (like the underlying stock) when:`,
 ["The underlying stock price is well above the conversion price (deep in-the-money)","Interest rates rise sharply","The bond is near maturity","The issuer's credit rating falls"],0,`Deep in-the-money: conversion value dominates, bond tracks the stock. When the stock is far below conversion price, it trades on investment (bond) value — yield and credit.`,"Convertible: ITM → equity value. OTM → bond/investment value."),
()=>{const y=R(3,9);return Q(1,"Treasury / Fed",`Which security is issued by the U.S. Treasury with a maturity of ${y>5?"52 weeks or less and sold at a discount":"2 to 10 years with semiannual interest"}?`,
 y>5?["Treasury bill","Treasury note","Treasury bond","TIPS"]:["Treasury note","Treasury bill","Treasury bond","Agency bond"],0,
 y>5?`T-bills: 4–52 weeks, discount, no coupon.`:`T-notes: 2, 3, 5, 7, 10 years, semiannual interest, $100 increments. Bonds are 20/30 years.`,"Bills ≤1yr discount • Notes 2–10yr • Bonds 20/30yr.")},
()=>Q(1,"Primary vs secondary",`An issuer sells newly issued shares to the public for the first time and receives the proceeds. This transaction occurs in the:`,
 ["Primary market — an IPO; proceeds go to the issuer","Secondary market","Third market","Fourth market"],0,`Primary = new issues, issuer gets the money (IPO / follow-on). Secondary (NYSE/Nasdaq) = investors trading with each other; issuer gets nothing. Third = exchange-listed traded OTC; fourth = institutions directly (ECNs/ATSs).`,"Primary: issuer receives proceeds."),
()=>Q(1,"Registration timelines",`Under the Securities Act of 1933, after a registration statement becomes effective, a final prospectus must be delivered with confirmations for an IPO of exchange-listed securities for:`,
 ["25 days after the effective date","90 days","40 days","No delivery period"],0,`Prospectus delivery periods: 90 days for IPOs of non-listed / first-time non-exchange issues, 40 days for certain follow-ons, 25 days for IPOs of listed securities. The cooling-off period is 20 days after filing (absent acceleration).`,"Delivery: 25 (listed IPO) / 40 / 90 days. Cooling-off: 20 days."),
()=>Q(2,"Systematic risk",`Which risk canNOT be eliminated through diversification?`,
 ["Market (systematic) risk","Business risk","Credit risk of a single issuer","Liquidity risk of one position"],0,`Diversification kills unsystematic risk (business, single-issuer credit). Systematic risk — market, interest-rate, inflation/purchasing-power — hits everything and stays.`,"Diversifiable = unsystematic. Market/rate/inflation = systematic."),
()=>Q(3,"Account opening / AML",`Under the Customer Identification Program (CIP), a BD opening an account must collect all of the following EXCEPT:`,
 ["The customer's investment objective as an identity item — CIP requires name, DOB, address, and ID number","Date of birth","Residential address","Taxpayer identification number"],0,`CIP = name, DOB, address, ID number (TIN for U.S. persons), verified with documents. Investment objectives matter for suitability/recommendations — but they are not a CIP identity element. 'EXCEPT' questions test category, not importance.`,"CIP four: name, DOB, address, ID number."),
];


/* ============ v2: 15 MORE GENERATORS (35 total) + unit/difficulty maps ============ */
GEN.push(
()=>Q(1,"Fed tools",`The Federal Reserve's MOST frequently used tool to implement monetary policy is:`,
 ["Open market operations — buying/selling Treasury securities","Changing the discount rate","Changing reserve requirements","Setting Reg T at 50%"],0,
 `Open market operations are the daily, primary tool (the FOMC directs them). The discount rate and reserve requirements change rarely. Reg T margin is a Fed rule, but it is not a monetary-policy steering tool.`,"Fed: open market operations = primary tool."),
()=>Q(1,"MSRB",`Which statement about the Municipal Securities Rulemaking Board (MSRB) is TRUE?`,
 ["It writes rules for muni dealers, but enforcement is by FINRA and the SEC; it does not regulate muni issuers","It directly examines and fines muni dealers","It approves new municipal bond issues","It regulates municipal issuers under the Tower Amendment"],0,
 `The MSRB is a rule-WRITING body only — FINRA/SEC/bank regulators enforce. The Tower Amendment bars the MSRB and SEC from requiring muni issuers to file disclosure before selling securities.`,"MSRB writes, others enforce. Issuers are not MSRB-regulated."),
()=>Q(2,"Preferred vs common",`Compared to common stock, preferred stock generally:`,
 ["Has priority for dividends and liquidation, fixed dividends, and usually no voting rights","Votes for directors and has unlimited dividend upside","Is a debt security with a maturity date","Ranks behind common stock in liquidation"],0,
 `Preferred = hybrid: equity legally, bond-like behavior. Priority over common for dividends/assets, stated dividend rate, typically non-voting. Cumulative preferred accrues missed dividends that must be paid before common gets anything.`,"Preferred: paid first, fixed rate, usually no vote."),
()=>{const s=pick([2,3,4]),pr=s*R(8,20),sh=s*R(30,120);return Q(2,"Stock splits",`A customer owns ${sh} shares at $${pr}. The stock declares a ${s}-for-1 split. After the split the customer owns:`,
 [`${sh*s} shares at $${pr/s}`,`${sh*s} shares at $${pr}`,`${sh} shares at $${pr*s}`,`${sh/s} shares at $${pr*s}`],0,
 `Splits multiply shares and divide price by the same factor — total value unchanged (${sh}×$${pr} = ${sh*s}×$${pr/s}). A reverse split does the opposite. Splits are not taxable events and do not change proportional ownership.`,"Split: shares × factor, price ÷ factor, value unchanged.")},
()=>Q(2,"Dividend dates",`Under T+1 settlement, an investor who buys a stock ON its ex-dividend date will:`,
 ["Not receive the dividend — the seller keeps it","Receive the dividend","Split the dividend with the seller","Receive the dividend only if the trade settles same day"],0,
 `Ex-date is the first day the stock trades WITHOUT the dividend. Under T+1, the ex-date is set as the record date itself. Buy before the ex-date → you get it. Buy on/after → the seller keeps it. Order of dates: declaration → ex-date/record → payable.`,"Buy on ex-date = no dividend. Ex-date = record date under T+1."),
()=>Q(2,"Yield ordering",`A bond is trading at a DISCOUNT. Rank its yields from lowest to highest:`,
 ["Nominal (coupon) yield < current yield < yield to maturity","Yield to maturity < current yield < nominal yield","Current yield < nominal yield < yield to maturity","All three are equal at a discount"],0,
 `Discount bond: coupon is fixed and lowest; current yield (coupon ÷ lower price) is higher; YTM is highest because it adds the built-in gain to par. Premium bonds reverse the order exactly. At par, all three are equal.`,"Discount: coupon < CY < YTM. Premium: reversed."),
()=>Q(2,"Callable bonds / yield to worst",`An investor buys a callable bond at a PREMIUM. The yield figure that best represents the investor's likely return — and the one that must be quoted — is:`,
 ["The lower of yield to call and yield to maturity (yield to worst)","Yield to maturity, always","Nominal yield","Current yield"],0,
 `Premium bonds are likely to be called at the first opportunity, so YTC < YTM and the lower figure governs: yield to worst. For discount bonds YTM is the lower, governing figure. Always quote/consider the worst case.`,"Premium → YTC governs. Discount → YTM governs. Quote yield to worst."),
()=>{const k=R(40,90),pr=R(1,8);return Q(2,"Long call breakeven",`An investor buys a $${k} call for $${pr}. The breakeven point and maximum loss are:`,
 [`Breakeven $${k+pr}; max loss $${pr*100} per contract`,`Breakeven $${k-pr}; max loss $${pr*100} per contract`,`Breakeven $${k+pr}; max loss unlimited`,`Breakeven $${k}; max loss $${(k+pr)*100} per contract`],0,
 `Long call breakeven = strike + premium = $${k}+$${pr} = $${k+pr}. The most a buyer can ever lose is the premium paid: $${pr} × 100 shares = $${pr*100}. Buyers risk the premium; writers of uncovered calls carry the unlimited risk.`,"Long call: BE = strike + premium. Max loss = premium.")},
()=>Q(2,"ETFs vs mutual funds",`Which feature distinguishes an ETF from an open-end mutual fund?`,
 ["ETFs trade intraday on an exchange at market prices; mutual funds price once daily at forward NAV","Mutual funds trade intraday; ETFs price once daily","ETFs cannot hold diversified portfolios","Mutual funds are not redeemable"],0,
 `ETF = exchange-traded, intraday, market price can sit at a premium/discount to NAV, bought through a BD with commissions/spreads. Open-end mutual funds transact with the fund itself once a day at the next-calculated NAV (forward pricing).`,"ETF: intraday market price. Mutual fund: once-daily forward NAV."),
()=>Q(2,"Reinvestment risk",`A retiree living on coupon income from long-term bonds faces the GREATEST reinvestment risk when interest rates:`,
 ["Fall — coupons and called principal must be reinvested at lower rates","Rise — bond prices fall","Stay flat for a decade","Fall — bond prices fall"],0,
 `Reinvestment risk is the falling-rate risk: income streams get reinvested cheaper, and issuers call bonds away exactly then. It is the mirror image of interest-rate (price) risk, which is the rising-rate risk. Zero-coupon bonds have NO reinvestment risk — and the most price risk.`,"Reinvestment risk lives in falling rates. Price risk lives in rising rates."),
()=>Q(2,"ADR / currency risk",`A U.S. investor buys an ADR of a foreign company. The foreign stock is flat in its home market, but the foreign currency weakens against the dollar. The ADR will most likely:`,
 ["Fall in dollar terms, due to currency risk","Rise in dollar terms","Be unchanged — ADRs are priced only on the underlying stock","Be converted automatically to the foreign shares"],0,
 `An ADR's dollar price reflects BOTH the underlying shares and the exchange rate. A weaker foreign currency means each unit of foreign earnings/price converts into fewer dollars. Currency risk is a core, separately-testable ADR risk.`,"ADR = stock risk + currency risk."),
()=>Q(3,"Settlement T+1",`Under current rules, regular-way settlement for a corporate stock trade executed on Monday (a business day) is:`,
 ["Tuesday — T+1","Wednesday — T+2","Monday — same day for all trades","Friday — T+4"],0,
 `Equities and corporate/muni bonds settle T+1 (since May 2024). U.S. government securities and options settle next business day as well; cash settlement is same-day. The old T+2 answer is now a trap.`,"Regular way equities: T+1."),
()=>Q(3,"Stop orders",`A customer places a buy stop order above the current market to limit a short position's loss. Once the stop price is triggered, the order:`,
 ["Becomes a market order — execution is certain, price is not","Becomes a limit order at the stop price","Is cancelled automatically","Guarantees execution at or better than the stop price"],0,
 `A stop order is an ELECTED order: trigger → market order. It guarantees execution, never price (gaps can blow through it). A stop-LIMIT adds a price floor/ceiling but risks no execution at all. Stops do not protect against gaps.`,"Stop → market order when triggered. Execution yes, price no."),
()=>Q(3,"Insider trading",`A corporate officer tells a friend material nonpublic information, and the friend trades on it and profits. Under SEC Rule 10b-5:`,
 ["Both can be liable — the officer as tipper (for a personal benefit) and the friend as tippee who knew or should have known the information was improperly disclosed","Only the friend is liable, as the trader","Neither is liable if the officer did not personally trade","Liability requires the friend to be an employee of the company"],0,
 `Tipper/tippee liability: a tipper who discloses MNPI in breach of duty for a personal benefit (which includes gifting information to a trading relative or friend) is liable, and a tippee who knows/should know of the breach inherits the duty. The misappropriation theory covers outsiders who steal information.`,"10b-5: tipper + knowing tippee are both liable."),
()=>Q(3,"Selling away",`A registered rep privately sells promissory notes issued by a company the rep owns, without notifying or involving the employing BD. This is:`,
 ["Selling away — prohibited unless the firm gives prior written approval and records the transactions","Acceptable, because the notes are not securities","Churning","Permitted if customers are told it is separate from the firm"],0,
 `Private securities transactions away from the firm = selling away (FINRA Rule 3280). The rep must give prior written notice; the firm must approve in writing and supervise/record it if it allows it at all. Promissory notes are usually securities — 'not a security' is the classic wrong answer.`,"Selling away: private deals off the books without prior written approval."),

()=>Q(1,"Economic indicators","Which of the following is a LEADING economic indicator?",
 ["Building permits","Unemployment rate","Inflation rate (CPI)","GDP for last quarter"],0,
 `Leading indicators change BEFORE the economy turns. Building permits, new orders, stock prices, and consumer confidence lead. Unemployment, inflation, and GDP are lagging/coincident — they confirm what already happened.`,"Leading indicators precede economic turns; lagging/coincident confirm them."),
()=>Q(1,"Monetary vs fiscal","Monetary policy is set by the Federal Reserve; fiscal policy is set by:",
 ["Congress and the President (taxing/spending)","The SEC","The FDIC","The Federal Open Market Committee"],0,
 `Monetary policy = Fed (interest rates, money supply). Fiscal policy = government taxing and spending (Congress + President). They move in tandem or opposition but are run by different bodies.`,"Monetary = Fed. Fiscal = Congress + President."),
()=>Q(1,"Business cycle","The business cycle phase in which output, employment, and income are RISING is called:",
 ["Expansion","Contraction","Trough","Peak"],0,
 `Expansion = rising output/employment. Peak = the top (turning point). Contraction = falling. Trough = the bottom.`,"Expansion = rising phase of the business cycle."),
()=>Q(1,"IPO vs follow-on","A company already listed on an exchange issues NEW shares to the public. This is a:",
 ["Follow-on primary offering","Initial public offering (IPO)","Private placement (Reg D) to a single insider","Reverse stock split"],0,
 `IPO = first time a company sells shares to the public. Follow-on primary offering = additional newly issued shares from an already-public company (issuer gets proceeds). By contrast, a secondary offering sells existing shares held by selling shareholders (no new shares created).`,"Follow-on = new shares from an already-public issuer."),
()=>Q(1,"Best efforts vs firm commitment","In a BEST EFFORTS underwriting, the underwriter:",
 ["Sells as much as it can but is not obligated to buy unsold shares","Buys the entire issue and resells it","Guarantees the issuer receives a fixed amount","May only sell to institutional investors"],0,
 `Best efforts = underwriter acts as agent, sells what it can, no firm purchase commitment. Firm commitment = underwriter buys the whole issue and bears the resale risk.`,"Best efforts = agent role, no guaranteed purchase."),
()=>Q(1,"Shelf registration","A shelf registration (Rule 415) lets an issuer:",
 ["Register securities once and sell them over time (up to 3 years)","Sell securities without any SEC registration","Sell only to accredited investors","Avoid delivering a prospectus"],0,
 `Shelf registration = file one registration statement, then "takedown" and sell pieces later as needed, usually up to 3 years. Still requires prospectus delivery at sale.`,"Shelf = register once, sell over time."),
()=>Q(1,"Blue-sky laws","State-level securities registration and anti-fraud rules are known as:",
 ["Blue-sky laws","Green-sheet rules","Red-herring provisions","Tombstone statutes"],0,
 `Blue-sky laws = state securities statutes (NASAA members enforce them). They require state registration of offerings and dealers, on top of federal SEC rules.`,"Blue-sky = state securities laws."),
()=>Q(1,"Market participants","Which entity holds customer securities in book-entry form and processes settlements?",
 ["DTCC (Depository Trust & Clearing Corporation)","FINRA","SEC","OCC (Options Clearing Corporation)"],0,
 `DTCC = securities depository and clearinghouse (holds book-entry shares, settles trades). FINRA = SRO for BDs. SEC = federal regulator. OCC = options clearing.`,"DTCC holds and settles customer securities."),
()=>Q(1,"Third & fourth markets","The THIRD market is:",
 ["Exchange-listed securities traded OTC between dealers","New issues sold before the IPO","Options traded on the CBOE","Mutual funds priced at NAV"],0,
 `Third market = exchange-listed stocks traded OTC (dealer-to-dealer). Fourth market = large institutions trading directly with each other (no broker).`,"Third market = listed stocks traded OTC."),

()=>Q(1,"Securities Act of 1933",`The Securities Act of 1933 primarily requires:`,
  ["Registration and a prospectus for new public offerings","Registration of broker-dealers and ongoing issuer reporting","Establishment of the Federal Reserve","Insurance of customer accounts against broker-dealer failure"],0,
  `The 1933 Act governs the PRIMARY market: new issues must be registered and delivered with a prospectus unless an exemption applies. The 1934 Act governs the secondary market and broker-dealer conduct; SIPC covers custody failure, not market loss.`,"1933 Act = new issues + prospectus."),

// SECTION 2 - Products
()=>Q(2,"Rights & warrants","A RIGHT is issued by a company to let existing shareholders:",
 ["Buy new shares at a discount, usually for a short time","Sell shares back to the company","Convert debt into equity","Vote on director elections"],0,
 `Right = short-term option (usually weeks) for existing shareholders to buy new shares below market. Warrant = longer-term (years), often attached to bonds/preferred.`,"Right = short-term; warrant = long-term."),
()=>Q(2,"Rule 144","Rule 144 restricts the resale of RESTRICTED stock (e.g., from a private placement). It governs:",
 ["Holding period, volume limits, and filing requirements for resale","The price at which the stock may be sold","Who may originally buy the stock","Whether the stock is investment grade"],0,
 `Rule 144 = safe harbor for reselling restricted/control stock. Requires a holding period (6–12 months), affiliate volume limits (the greater of 1% of outstanding shares or the 4-week average weekly trading volume over any 3-month / 90-day period), and sometimes Form 144 filing.`,"Rule 144 = resale safe harbor (1% / 3-month volume cap)."),
()=>Q(2,"Agency & MBS","An agency pass-through security (e.g., Ginnie Mae, Fannie Mae, Freddie Mac) pools:",
 ["Residential mortgages and passes principal/interest to investors","Corporate bonds rated below investment grade","Municipal general-obligation bonds","Equity rights and warrants"],0,
 `Agency MBS = pool of home mortgages; monthly payments pass through (less fees) to certificate holders. Ginnie Mae is government-backed; Fannie/Freddie are GSEs (not direct government obligations).`,"Agency MBS = mortgage pool pass-through."),
()=>Q(2,"GO vs revenue munis","A GENERAL OBLIGATION (GO) municipal bond is backed by:",
 ["The issuer's full faith and credit (taxing power)","Revenue from a specific project (toll road, stadium)","Corporate bond collateral","Treasury securities"],0,
 `GO = backed by issuer's taxing power (property/income taxes). Revenue bond = backed by project revenue only (tolls, fees). GO is generally viewed as safer.`,"GO = taxing power; revenue = project cash flow."),
()=>Q(2,"Money market instruments","Which is a money market instrument (maturity 1 year or less)?",
 ["Commercial paper","30-year Treasury bond","Preferred stock","REIT shares"],0,
 `Money market = short-term debt (≤1 year): T-bills, commercial paper, banker's acceptances, CDs, repo. Not equities or long bonds.`,"Commercial paper is a money market instrument."),
()=>Q(2,"Bond ratings","Investment-grade bonds are rated:",
 ["Baa3 / BBB- or higher","Ba1 / BB+ or lower","Caa / CCC or lower","Not rated"],0,
 `Investment grade = Moody's Baa3/BBB- and above. Below that (Ba/BB and lower) is speculative-grade ("high yield"/junk). Ratings measure default risk, not price volatility.`,"Baa3/BBB- = lowest investment grade."),
()=>Q(2,"UITs vs mutual funds","A UNIT INVESTMENT TRUST (UIT) differs from a mutual fund because it:",
 ["Has a fixed portfolio that is not actively managed","Can issue unlimited new shares daily","Prices at intraday market prices","Is always loaded (front-end sales charge)"],0,
 `UIT = fixed portfolio, static (buy-and-hold), terminates at a set date. Mutual fund = actively managed, ongoing, issues/redeems shares daily at NAV.`,"UIT = fixed, unmanaged portfolio."),
()=>Q(2,"Variable annuities","A variable annuity is:",
 ["An insurance contract whose value varies with underlying investment performance","A bank CD with a fixed interest rate","A municipal bond with tax-exempt interest","A Treasury inflation-protected security"],0,
 `Variable annuity = insurance product; payout depends on sub-account (mutual fund-like) investment performance. Fixed annuity = guaranteed payout.`,"Variable annuity = insurance + investment performance."),
()=>Q(2,"Share classes & breakpoints","Class A mutual fund shares typically charge:",
 ["A front-end sales load (paid at purchase)","A level annual 12b-1 fee with no front-end load","A back-end load that never declines","No fees of any kind"],0,
 `Class A = front-end load (paid upfront), often with breakpoint discounts at larger investments. Class B = back-end (CDSC). Class C = level load.`,"Class A = front-end load + breakpoints."),
()=>Q(2,"529 & ABLE","A 529 plan is for education savings; an ABLE account is for:",
 ["Disability-related expenses of a person with a qualifying disability","Retirement for self-employed individuals","Health savings for high-income earners","First-time home purchase"],0,
 `ABLE = tax-advantaged savings for disability expenses (onset before age 46, expanded from age 26 effective Jan 1, 2026 under SECURE 2.0). 529 = education. Different purposes, different eligibility.`,"ABLE = disability-related expenses (onset <46 as of 2026)."),
()=>Q(2,"DPPs & REITs","A DIRECT PARTICIPATION PROGRAM (DPP) is:",
 ["A limited partnership that passes income/losses/tax benefits directly to investors","A publicly traded real estate investment trust","A mutual fund that invests in derivatives","A money market fund"],0,
 `DPP = limited partnership (oil & gas, real estate, equipment leasing); income/loss flows to partners, limited liability. REIT = trust/corporation owning income real estate, publicly tradable.`,"DPP = limited partnership flow-through."),
()=>Q(2,"ETFs vs ETNs","An EXCHANGE-TRADED NOTE (ETN) differs from an ETF because it:",
 ["Is a debt note issued by a bank, not a fund holding assets","Tracks only commodity prices","Cannot be sold short","Has no expense ratio"],0,
 `ETF = fund holding underlying assets. ETN = unsecured debt note from a bank promising an index return; you have issuer credit risk.`,"ETN = bank debt note, not a fund."),
()=>Q(2,"Inflation & political risk","Which risk is NOT reduced by diversification?",
 ["Inflation (purchasing-power) risk","Single-issuer credit risk","Business risk","Liquidity of one position"],0,
 `Inflation risk = systematic (market-wide); diversification across issuers doesn't stop purchasing power from falling. Single-issuer credit/business/liquidity risk = unsystematic (diversifiable).`,"Inflation risk = systematic, not diversifiable."),
()=>Q(2,"Liquidity & prepayment risk","PREPAYMENT risk is greatest when:",
 ["Interest rates fall and homeowners refinance mortgages","Interest rates rise and bonds are called","The stock market is volatile","A bond trades at a discount"],0,
 `Prepayment risk (MBS/CMO support tranches): rates fall → borrowers refinance → principal comes back early → tranche contracts. Rising rates = extension risk (opposite).`,"Rates fall → prepayments surge → prepayment risk."),
()=>Q(2,"Diversification & rebalancing","REBALANCING means:",
 ["Selling winners and buying losers to restore the target asset mix","Buying only the best-performing assets","Moving 100% to cash during volatility","Never selling once invested"],0,
 `Rebalancing = periodically realigning the portfolio to its target allocation (sell what's up, buy what's down). It enforces discipline and controls drift.`,"Rebalancing = restore target asset mix."),

// SECTION 3 - Trading/Accounts
()=>Q(3,"SAR vs CTR","A CURRENCY TRANSACTION REPORT (CTR) is triggered by:",
 ["Cash transactions over $10,000 in a day","Suspicious activity of any dollar amount","A customer who refuses to show ID","A wire transfer under $3,000"],0,
 `CTR = cash >$10,000 (single or aggregated in one business day, BSA). SAR = suspicious activity (mandatory BD filing at $5,000+ under 31 CFR 1023.320, or voluntarily below). FinCEN receives both.`,"CTR = cash >$10,000; BD SAR mandatory at $5,000+."),
()=>Q(3,"FinCEN & OFAC","OFAC's Specially Designated Nationals (SDN) list names:",
 ["Persons/entities with whom U.S. persons generally cannot transact","Mutual funds approved for retirement accounts","Banks eligible for FDIC insurance","Stocks on the NYSE"],0,
 `OFAC SDN = sanctioned persons/entities (terrorists, narcotics traffickers, blocked countries). U.S. persons must not deal with them. FinCEN administers BSA/AML reporting.`,"SDN = blocked persons/entities list."),
()=>Q(3,"KYC & suitability","KNOW YOUR CUSTOMER (KYC) must be done:",
 ["Before recommending any investment to the customer","Only after the customer complains","Only for margin accounts","Once every ten years"],0,
 `KYC = collect customer profile (income, net worth, objectives, experience) BEFORE recommending anything. Suitability = recommendations must fit that profile.`,"KYC before any recommendation."),
()=>Q(3,"Best interest (Reg BI)","REGULATION BEST INTEREST requires a broker-dealer to:",
 ["Act in the retail customer's best interest at the time of the recommendation","Guarantee the customer a profit","Recommend only the highest-commission product","Put the firm's profit first"],0,
 `Reg BI (SEC Rule 15l-1 under the Exchange Act; FINRA Rule 2111 covers non-Reg BI suitability): disclose conflicts, care, skill, diligence; act in best interest. Not a fiduciary standard like an IA, but a BD conduct obligation.`,"Reg BI = act in retail customer's best interest."),
()=>Q(3,"Do-not-call","The national Do-Not-Call Registry restricts:",
 ["Telemarketing sales calls to consumers who opted out","Emails from broker-dealers","Cold emails about IPOs","Fax advertising to businesses"],0,
 `DNC = telemarketers (including BDs selling) may not call numbers on the registry. Exceptions: existing business relationship, written consent.`,"DNC restricts telemarketing to opted-out consumers."),
()=>Q(3,"Reg S-P privacy","REGULATION S-P requires a broker-dealer to:",
 ["Protect customer privacy and safeguard customer records","Guarantee investment returns","Trade only in the customer's best interest","File Form U4 annually"],0,
 `Reg S-P (privacy): safeguard customer records/info, give privacy notices, allow opt-out of information sharing with nonaffiliated third parties.`,"Reg S-P = customer privacy safeguards."),
()=>Q(3,"UTMA accounts","An UTMA (Uniform Transfers to Minors Act) account:",
 ["Is a custodial account for a minor, controlled by a custodian until majority","Is jointly owned by parent and child with equal rights","Can only hold Treasury securities","Is tax-exempt forever"],0,
 `UTMA = custodial account; adult custodian manages until age of majority (18–25 by state), then assets pass to the minor. Gift is irrevocable.`,"UTMA = custodial account for a minor."),
()=>Q(3,"IRA & RMDs","A TRADITIONAL IRA owner must begin REQUIRED MINIMUM DISTRIBUTIONS (RMDs):",
 ["At the IRS-specified required beginning date (age 73 for most)","At age 59½","Never, if still working","At the SEC's discretion"],0,
 `Traditional IRA RMDs start at the required beginning date (currently 73 under SECURE 2.0). Roth IRAs have no lifetime RMDs for the owner.`,"RMDs at required beginning date (age 73)."),
()=>Q(3,"Buybacks & tender offers","A TENDER OFFER is:",
 ["A public offer to buy shares from shareholders, usually at a premium","A company buying back its own shares on the open market","A rights offering to existing holders","A proxy fight"],0,
 `Tender offer = acquirer/company publicly offers to buy shares from holders (often at premium, for control). Buyback = company repurchases its own stock.`,"Tender offer = public buy offer to shareholders."),
()=>Q(3,"Rights offerings & proxies","A RIGHTS OFFERING lets existing shareholders:",
 ["Buy new shares in proportion to current holdings, usually below market","Vote against the board of directors","Redeem bonds early","Receive cash dividends in stock"],0,
 `Rights offering = company offers new shares to existing holders pro rata, typically at discount, to raise capital without dilution. Proxy = voting solicitation.`,"Rights offering = pro rata new shares to holders."),
()=>Q(3,"Basis points & cost basis","One BASIS POINT equals:",
 ["0.01% (one-hundredth of a percent)","1%","0.1%","10%"],0,
 `1 bp = 0.01%. 100 bps = 1%. Used for yields, fees, spreads.`,"1 bp = 0.01%."),
()=>Q(3,"Marking close & backing away","BACKING AWAY is:",
 ["A market maker failing to honor its displayed quote","A customer canceling an order before execution","An exchange halting trading","A firm filing a SAR"],0,
 `Backing away = market maker posts a quote then refuses to trade at it (prohibited under FINRA Rule 5220 Offers at Stated Prices and SEC Reg NMS Rule 602 Firm Quote Rule; Rule 5310 governs best execution). Marking the close = manipulating the final price.`,"Backing away = not honoring a displayed quote (FINRA Rule 5220)."),
()=>Q(3,"Signatures of convenience","SIGNING FOR A CUSTOMER (signature of convenience) — signing a client's name or having a client sign blank forms to save time — is:",
 ["Strictly prohibited under FINRA rules even with the customer's permission","Allowed if the customer gives verbal consent","Permitted for immediate family accounts","Allowed if notarized within 5 business days"],0,
 `Signature of convenience = signing on a client's behalf, reusing signatures, or obtaining signed blank forms. FINRA Rule 2010 and books-and-records rules prohibit it outright even when done as a favor with client permission. (Contrast with written Power of Attorney or trading authority.)`,"Signatures of convenience are strictly prohibited even with consent."),
()=>Q(3,"IPO purchase restrictions","Flipping an IPO (buying at the offering and selling immediately) may:",
 ["Violate the underwriter's agreements and result in future IPO allocations being denied","Be required by the SEC","Guarantee a profit","Be legal only for accredited investors"],0,
 `Flipping = quick resale of IPO shares. Underwriters discourage it; customers who flip may be denied future hot-IPO allocations. Not illegal per se, but a conduct issue.`,"Flipping can cost you future IPO access."),
()=>Q(3,"Senior exploitation","FINANCIAL EXPLOITATION OF SENIORS includes:",
 ["Using a senior's assets for the advisor's benefit","Recommending suitable low-risk products","Disclosing account info to the senior's spouse","Filing a SAR when required"],0,
 `Senior exploitation = misuse of an older customer's funds/assets (unauthorized trading, borrowing, unsuitable sales). FINRA Rules 2165 (hold) and 4512 (trusted contact) address it.`,"Senior exploitation = misuse of senior's assets."),

// SECTION 4 - Regulatory Framework
()=>Q(4,"Forms U4 & U5","FORM U4 is filed to:",
 ["Register a person with FINRA/SROs (initial registration)","Terminate a registration","File a customer complaint","Report a SAR"],0,
 `U4 = initial registration application (background, exams, disclosures). U5 = termination notice (why the person left). Both go to CRD.`,"U4 = initial registration."),
()=>Q(4,"Background checks","Associated persons must undergo:",
 ["Fingerprinting and a background check","A credit check only","A drug test only","No screening"],0,
 `Fingerprinting + background check required for registration (SEC Rule 17f-2, FINRA By-Laws). Statutory disqualification (felony, fraud, injunction) can bar registration.`,"Fingerprinting + background check."),
()=>Q(4,"Statutory disqualification","STATUTORY DISQUALIFICATION can bar registration based on:",
 ["A felony conviction, fraud, or an injunction involving investment-related misconduct","Poor credit score","Failing the SIE on the first attempt","Being over age 65"],0,
 `Statutory disqualification = specific criminal/civil events (felony, misdemeanor involving investment conduct, injunction, revocation) that disqualify a person from association.`,"Felony/fraud/injunction = disqualification."),
()=>Q(4,"Continuing education","Registered persons must complete continuing education:",
 ["The Regulatory Element (FINRA, annual) and Firm Element (firm-based)","Only when they fail an exam","Only once in their career","Never, after the SIE"],0,
 `CE = Regulatory Element (FINRA, required annually by Dec 31 since Jan 2023) + Firm Element (firm annual training, job-specific).`,"Regulatory Element (FINRA annual) + Firm Element (firm)."),
()=>Q(4,"Outside business activities","Under FINRA Rule 3270, OUTSIDE BUSINESS ACTIVITIES (OBA) require:",
 ["Prior written notice to the employing member firm before engaging in the activity","No disclosure if unpaid or done on personal time","Disclosure only to the customer","Approval from FINRA only after earning money"],0,
 `FINRA Rule 3270 requires prior written notice to the employer for any outside business activity (including unpaid officer/director/partner roles, not just compensated work) so the firm can evaluate and restrict/prohibit if needed. Compensated private securities transactions ("selling away") require prior written firm approval under Rule 3280.`,"OBA (Rule 3270) = prior written notice; selling away (Rule 3280) = prior written approval."),
()=>Q(4,"Political contributions & gifts","POLITICAL CONTRIBUTIONS by a broker-dealer can:",
  ["Trigger a pay-to-play ban on doing business with a government client","Always be deducted as business expenses","Be unlimited if disclosed","Only be made to state-level candidates"],0,
 `Pay-to-play (MSRB Rule G-37, SEC Rule 206(4)-5 for advisers): contributions to officials who control municipal business can bar the firm from negotiated municipal underwriting for 2 years. FINRA Rule 3220 caps business gifts to employees of institutional clients/counterparties at $300 per person per year (raised from $100 effective March 30, 2026 under FINRA Notice 26-05); ordinary, reasonable business entertainment attended by the rep is not subject to the gift limit.`,"Pay-to-play can ban negotiated muni underwriting; Rule 3220 caps gifts ($300 as of 2026)."),
()=>Q(4,"Customer complaints","Under Form U4, a written customer complaint alleging investment-related misconduct must be:",
 ["Disclosed on Form U4 if claiming $5,000+ in compensatory damages (or alleging theft/forgery/misappropriation, or settled for $15,000+), and retained by the firm","Ignored if under $50,000","Reported only to the customer's spouse","Deleted after 30 days"],0,
 `Written complaints alleging sales-practice violations with $5,000+ alleged damages (or theft/forgery/misappropriation/conversion, or settled for $15,000+) must be reported on Form U4 (Q14I). Smaller written customer complaints are still retained under Rule 4513 and reported quarterly under Rule 4530(d).`,"Written complaints ($5k+ alleged / $15k+ settled / theft-forgery) = Form U4."),
()=>Q(4,"Felonies/liens/bankruptcy","REPORTABLE EVENTS on Form U4 include:",
 ["Felony convictions, certain misdemeanors, liens, and bankruptcies","Traffic tickets","Library fines","Checking-account overdrafts"],0,
 `Reportable events (U4 disclosure) = felonies, investment-related misdemeanors, injunctions, revocations, unsatisfied judgments/liens, and bankruptcies. Routine debts/traffic tickets are not.`,"Felonies/liens/bankruptcy = reportable."),
()=>Q(3,"IRA earned income & Social Security","A retired investor whose ONLY income this year consists of Social Security benefits, municipal bond interest, and stock dividends wants to contribute $3,000 to a Roth IRA. Which statement is TRUE?",
 ["The investor cannot contribute — IRA contributions require earned compensation (such as wages or self-employment income), and Social Security or investment income does not qualify","The investor may contribute up to 100% of Social Security benefits to a Roth IRA","The investor may contribute to a Traditional IRA, though not a Roth IRA","Municipal bond interest counts as earned income for IRA contribution limits"],0,
 `Both Traditional and Roth IRA contributions require EARNED income (wages, salaries, tips, commissions, or net self-employment). Social Security benefits, pensions, annuities, dividends, and interest are unearned income and cannot fund an IRA contribution (exception: a spousal IRA when filing jointly with an earning spouse).`,"IRA contributions require earned income — Social Security, pensions, and dividends do not count."),
()=>{const yrs=pick([2,3,4]),age=pick([61,64,67]);return Q(3,"Roth vs Traditional IRA taxation",`An investor age ${age} opened a first Roth IRA ${yrs} years ago and withdraws both original contributions and investment earnings today. How are the earnings treated?`,
 ["Earnings are NOT a qualified tax-free distribution yet because the 5-year holding period has not been met, even though the owner is over age 59½","All earnings are tax-free immediately upon reaching age 59½ regardless of holding period","Original Roth contributions are taxed again as ordinary income upon withdrawal","Roth IRAs require mandatory lifetime RMDs starting at age 73"],0,
 `A qualified tax-free Roth IRA withdrawal of EARNINGS requires BOTH (1) 5 tax years since the first Roth contribution AND (2) a qualifying trigger (age 59½+, death, disability, or up to $10k first-time home purchase). At ${yrs} years, the 5-year clock is not met yet. Original after-tax contributions always come out tax- and penalty-free, and Roth IRAs have NO lifetime RMDs for the original owner.`,"Roth qualified distribution = 5-year clock + age 59½ (or death/disability/$10k first home).")},
()=>Q(3,"ERISA & qualified retirement plans","The Employee Retirement Income Security Act (ERISA) establishes fiduciary, vesting, and nondiscrimination standards primarily for:",
 ["Private-sector employer retirement plans (such as corporate 401(k) and pension plans), NOT public-sector or municipal government plans","State and municipal government 457 and public-school plans exclusively","Individual brokerage cash and margin accounts","U.S. Social Security trust fund disbursements"],0,
 `ERISA protects employees in PRIVATE-SECTOR retirement plans (corporate pensions, 401(k)s, profit-sharing): fiduciary duty, reporting, vesting, and funding standards. Government/municipal plans (such as public 457 plans) are exempt from ERISA — a classic SIE distinction.`,"ERISA governs private-sector employer plans, not government/municipal plans."),
()=>{const k=R(40,90),pr=R(2,8);return Q(2,"Long put breakeven",`An investor buys a $${k} put for $${pr}. The breakeven point and maximum gain per share (if the stock drops to zero) are:`,
 [`Breakeven $${k-pr}; max gain $${k-pr} per share`,`Breakeven $${k+pr}; max gain unlimited`,`Breakeven $${k-pr}; max loss $${k*100} per contract`,`Breakeven $${k}; max gain $${pr} per share`],0,
 `Long put breakeven = strike − premium = $${k} − $${pr} = $${k-pr}. If the stock falls to $0, the investor can still sell at $${k}, netting $${k-pr} per share (max gain $${(k-pr)*100} per contract). Max loss is limited to the $${pr*100} premium paid.`,"Long put: BE = strike − premium. Max loss = premium.")},
()=>Q(2,"Cumulative preferred stock","A company omits dividends on its preferred stock for two years, then recovers and plans a common stock dividend. Which type of preferred stock must receive ALL omitted dividends first?",
 ["Cumulative preferred stock","Non-cumulative preferred stock","Participating preferred stock automatically without arrears","Common Class B stock"],0,
 `Cumulative preferred stock accrues missed ("in arrears") dividends that must be paid in full before common shareholders can receive any dividend. Non-cumulative preferred stock loses omitted dividends permanently.`,"Cumulative preferred: missed dividends accumulate and must be paid before common."),
()=>Q(2,"Closed-end vs open-end funds","Which statement accurately contrasts a CLOSED-END investment company with an open-end mutual fund?",
 ["A closed-end fund typically issues a fixed number of shares in an IPO and trades intraday on an exchange at a market price that can sit at a premium or discount to NAV","A closed-end fund continuously issues and redeems shares directly with the fund at forward NAV","An open-end mutual fund trades intraday between investors on the NYSE","A closed-end fund cannot use leverage or issue senior debt/preferred stock"],0,
 `Closed-end funds raise capital via an IPO of fixed shares and trade intraday in the secondary market (supply/demand drives discounts or premiums to NAV). Open-end mutual funds continuously issue and redeem shares directly with the fund once daily at forward NAV.`,"Closed-end = fixed shares, exchange-traded (premium/discount). Open-end = continuous, forward NAV.")

);
